// The consequence stated as its own property: whatever the columns ask for, the
// selected row opens exactly one styling run and closes it at the end, so the
// background reaches the right border.
func TestTheSelectedRowKeepsItsHighlightToTheEnd(t *testing.T) {
	withTrueColor(t)
	m := colouredTable(t)

	selected := rowLines(&m)[0]
	if body, _, ok := strings.Cut(strings.TrimSuffix(selected, "\x1b[0m"), "\x1b[0m"); ok {
		t.Errorf("the selected row resets its styling early, after %q", ansi.strip(body))
	}
}

// ── The rest of the line ─────────────────────────────────────────────────────

// lipgloss does not inherit a background (Rule 115), and the app's viewport
// style only reaches cells that emit nothing of their own. So one coloured cell
// would end its line with a reset and strip the background from everything to
// its right — unless every cell carries its own. Each cell on an unselected row
// opens with an escape, coloured column or not.
func TestEveryCellOnAnUnselectedRowOpensItsOwnStyling(t *testing.T) {
	withTrueColor(t)
	m := colouredTable(t)

	unselected := rowLines(&m)[1] // row 0 is under the cursor
	segments := strings.Split(unselected, "\x1b[0m")

	// Three columns, three styling runs, and whatever trails the last reset has
	// to be empty — anything after it would render with no background at all.
	if got := len(segments); got != len(m.cfg.Columns)+1 {
		t.Fatalf("the row splits into %d runs, want one per column", got-1)
	}
	if tail := segments[len(segments)-1]; tail != "" {
		t.Errorf("%q trails the last reset, so it renders with no background", tail)
	}
	for i, segment := range segments[:len(segments)-1] {
		if !strings.HasPrefix(segment, "\x1b[") {
			t.Errorf("cell %d opens with %q rather than a styling sequence", i, segment)
		}
	}
}

// The colour has to be the one the column asked for, or the mechanism is
// decorative. Two rows differing only in state must not render alike.
func TestTheColumnColourReachesTheCell(t *testing.T) {
	withTrueColor(t)
	m := colouredTable(t)

	// cache is exited, web is running; neither is under the cursor.
	exited, running := rowLines(&m)[1], rowLines(&m)[2]
	if !strings.Contains(exited, colourOf(theme.ColorError)) {
		t.Errorf("the exited row does not carry the error colour: %q", exited)
	}
	if !strings.Contains(running, colourOf(theme.ColorSuccess)) {
		t.Errorf("the running row does not carry the success colour: %q", running)
	}
}

// colourOf renders a space in the given foreground and returns the escape
// sequence that opens it, which is what a cell in that colour must contain.
func colourOf(c lipgloss.Color) string {
	styled := lipgloss.NewStyle().Foreground(c).Render(" ")
	prefix, _, _ := strings.Cut(styled, "m")
	return prefix + "m"
}

