// Rule 116 at the level it is actually seen: every rendered line spans the same
// width, so the viewport border closes on a rectangle.
func TestEveryRenderedLineSpansTheSameWidth(t *testing.T) {
	withTrueColor(t)
	m := colouredTable(t)
	m.Resize(100, 6)

